use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use sqlx::postgres::PgPoolOptions;
use sqlx::PgPool;
use reqwest;

#[derive(Deserialize)]
struct WebhookConfig {
    callback_url: String,
    event_type: String,
    metadata: Option<String>,
}

#[derive(Serialize, Deserialize, sqlx::FromRow)]
struct WebhookRecord {
    id: i32,
    url: String,
    event_type: String,
    status: String,
}

async fn register_webhook(
    pool: web::Data<PgPool>,
    config: web::Json<WebhookConfig>,
) -> HttpResponse {
    // Validate the callback URL by making a HEAD request to verify it's reachable
    let validation_url = format!("{}/health", config.callback_url.trim_end_matches('/'));

    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(5))
        .build()
        .unwrap();

    let probe_result = client.head(&validation_url).send().await;

    let reachable = match probe_result {
        Ok(resp) => resp.status().is_success() || resp.status().is_redirection(),
        Err(_) => false,
    };

    if !reachable {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "callback_url is not reachable",
            "url_tested": validation_url
        }));
    }

    // Store the webhook registration
    let result = sqlx::query(
        "INSERT INTO webhooks (url, event_type, status, metadata) VALUES ($1, $2, 'active', $3)"
    )
    .bind(&config.callback_url)
    .bind(&config.event_type)
    .bind(&config.metadata)
    .execute(pool.get_ref())
    .await;

    match result {
        Ok(_) => HttpResponse::Created().json(serde_json::json!({
            "status": "registered",
            "callback_url": config.callback_url
        })),
        Err(e) => HttpResponse::InternalServerError().json(serde_json::json!({
            "error": format!("Failed to register webhook: {}", e)
        })),
    }
}

async fn list_webhooks(pool: web::Data<PgPool>) -> HttpResponse {
    let records = sqlx::query_as::<_, WebhookRecord>(
        "SELECT id, url, event_type, status FROM webhooks WHERE status = 'active'"
    )
    .fetch_all(pool.get_ref())
    .await;

    match records {
        Ok(hooks) => HttpResponse::Ok().json(hooks),
        Err(e) => HttpResponse::InternalServerError().json(serde_json::json!({
            "error": format!("Query failed: {}", e)
        })),
    }
}

async fn trigger_webhook(
    pool: web::Data<PgPool>,
    path: web::Path<i32>,
) -> HttpResponse {
    let webhook_id = path.into_inner();
    let record = sqlx::query_as::<_, WebhookRecord>(
        "SELECT id, url, event_type, status FROM webhooks WHERE id = $1"
    )
    .bind(webhook_id)
    .fetch_optional(pool.get_ref())
    .await;

    match record {
        Ok(Some(hook)) => {
            let client = reqwest::Client::new();
            let resp = client.post(&hook.url)
                .json(&serde_json::json!({"event": hook.event_type, "timestamp": chrono::Utc::now().to_rfc3339()}))
                .send()
                .await;
            match resp {
                Ok(r) => HttpResponse::Ok().json(serde_json::json!({"delivered": true, "status": r.status().as_u16()})),
                Err(e) => HttpResponse::BadGateway().json(serde_json::json!({"delivered": false, "error": e.to_string()})),
            }
        },
        Ok(None) => HttpResponse::NotFound().finish(),
        Err(e) => HttpResponse::InternalServerError().json(serde_json::json!({"error": e.to_string()})),
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let database_url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let pool = PgPoolOptions::new()
        .max_connections(5)
        .connect(&database_url)
        .await
        .expect("Failed to create pool");

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(pool.clone()))
            .route("/webhooks", web::post().to(register_webhook))
            .route("/webhooks", web::get().to(list_webhooks))
            .route("/webhooks/{id}/trigger", web::post().to(trigger_webhook))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
